INSERT INTO "revisions" VALUES('09c569016bdb143e5ecd4ab4e1942880ec094c1d0043416e17a1337113412f10','legacy_binary_names','{"entry":"main.nex","files":{"main.nex":"module legacy_binary_names;\npub struct bytes { data:list<i64>; }\nfn utf8_bytes(value:str) -> str { return value; }\nfn decode_utf8(value:str) -> str { return value; }\nfn encode_base64(value:str) -> str { return value; }\nfn decode_base64(value:str) -> str { return value; }\nfn identity<T:wire>(value:T) -> T { return unwrap(decode_json<T>(encode_json(value))); }\nfn transform(f:fn(bytes)->bytes,value:bytes) -> bytes { return f(value); }\nfn main() -> unit !{io} {\n  let original:bytes = bytes([0,255,128]);\n  let captured:fn(bytes)->bytes = fn(value:bytes)->bytes { return bytes(original.data+value.data); };\n  print(identity(transform(captured,bytes([1]))));\n  print(decode_base64(encode_base64(decode_utf8(utf8_bytes(\"Я🧠\")))));\n}\ntest fn preserved_names() -> unit {\n  assert(identity(bytes([0,255,128])).data==[0,255,128]);\n  assert(decode_base64(encode_base64(decode_utf8(utf8_bytes(\"text\"))))==\"text\");\n}\n"},"schema":"nex.sources/1"}','/Users/sae/projects/NEX/build/legacy-language-012-byte-names/main.nex','2026-10-18T03:25:55.173Z','0.12');
